package com.nth.desktop3d;

import android.content.*;
import android.graphics.Typeface;
import android.view.*;
import android.view.inputmethod.EditorInfo;
import android.widget.*;
import android.text.*;
import org.json.JSONArray;

/** A conversation surface with an independently scrolling transcript and a fixed composer. */
@android.annotation.SuppressLint("ViewConstructor")
final class NotaChatView extends LinearLayout {
    interface Host { void send(String text); void stop(); void changedCloud(boolean enabled); }
    final EditText question; final Button send; TextView answer; LinearLayout suggestions;
    private final Host host; private final SharedPreferences draft,storage; private final NotaConversation conversations;
    private final ScrollView scroll; private final LinearLayout transcript; private final TextView status; private final Switch cloud;
    private String pending; private boolean busy,search,syncingCloud;
    NotaChatView(Context c,SharedPreferences draft,Host host){
        super(c);this.host=host;this.draft=draft;storage=c.getSharedPreferences("nota_conversations",Context.MODE_PRIVATE);conversations=new NotaConversation(storage.getString("document",""));setOrientation(VERTICAL);search=draft.getBoolean("nota_web_always",false);
        scroll=new ScrollView(c);scroll.setFillViewport(true);scroll.setClipToPadding(false);scroll.setVerticalScrollBarEnabled(false);transcript=Ui.column(c);transcript.setPadding(0,Ui.dp(c,12),0,Ui.dp(c,12));scroll.addView(transcript,new ScrollView.LayoutParams(-1,-2));addView(scroll,new LayoutParams(-1,0,1));
        LinearLayout composer=Ui.column(c);composer.setPadding(Ui.dp(c,12),Ui.dp(c,6),Ui.dp(c,8),Ui.dp(c,8));composer.setBackground(Ui.touch(c,Ui.surface(0xF0132435,22,c),22));
        LinearLayout modes=Ui.row(c);cloud=new Switch(c);cloud.setText("Cloud questions");cloud.setTextColor(Ui.MUTED);cloud.setTextSize(12);cloud.setMinHeight(Ui.dp(c,44));cloud.setChecked(draft.getBoolean("cloud_ai",false));modes.addView(cloud,new LayoutParams(0,-2,1));Button web=Ui.quiet(c,search?"Web: Always":"Web: Auto",()->{search=!search;draft.edit().putBoolean("nota_web_always",search).apply();((Button)findViewWithTag("nota-search-mode")).setText(search?"Web: Always":"Web: Auto");});web.setTag("nota-search-mode");web.setTextSize(12);web.setContentDescription("Web search mode: automatic or always");modes.addView(web,new LayoutParams(-2,Ui.dp(c,44)));composer.addView(modes);
        cloud.setOnCheckedChangeListener((button,enabled)->{if(syncingCloud)return;if(enabled&&!draft.getBoolean("nota_chat_consent",false)){cloud.setChecked(false);android.app.AlertDialog dialog=new android.app.AlertDialog.Builder(c).setTitle("Allow cloud conversations?").setMessage("Your message and recent cloud conversation turns are sent to Nth Nota's AI service. Relevant search terms may be sent to public sources or the configured web-search provider. Launcher questions can include current setting values. Notes, cards and your app list are not attached. Conversations stay on this device. You can switch cloud questions off at any time.").setNegativeButton("Keep off",null).setPositiveButton("Enable cloud",(d,w)->{draft.edit().putBoolean("nota_chat_consent",true).apply();cloud.setChecked(true);}).create();Ui.themeDialog(dialog);return;}host.changedCloud(enabled);status();});
        LinearLayout input=Ui.row(c);input.setGravity(Gravity.BOTTOM);question=new EditText(c);question.setTextSize(16);question.setTextColor(Ui.TEXT);question.setHintTextColor(Ui.MUTED);question.setHint("Message Nth Nota");question.setContentDescription("Ask Nth Nota");question.setBackgroundColor(android.graphics.Color.TRANSPARENT);question.setPadding(0,Ui.dp(c,9),Ui.dp(c,8),Ui.dp(c,9));question.setMaxLines(4);question.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_FLAG_CAP_SENTENCES|android.text.InputType.TYPE_TEXT_FLAG_MULTI_LINE);question.setImeOptions(EditorInfo.IME_ACTION_SEND);question.setFilters(new InputFilter[]{new InputFilter.LengthFilter(2000)});input.addView(question,new LayoutParams(0,-2,1));send=Ui.primary(c,"↑",()->{if(busy)host.stop();else host.send(question.getText().toString());});send.setTextSize(24);send.setPadding(0,0,0,0);send.setTag("nota-send");input.addView(send,new LayoutParams(Ui.dp(c,48),Ui.dp(c,48)));composer.addView(input,new LayoutParams(-1,-2));addView(composer,new LayoutParams(-1,-2));
        status=Ui.text(c,"",11,Ui.MUTED);status.setPadding(Ui.dp(c,4),Ui.dp(c,5),0,0);status.setAccessibilityLiveRegion(ACCESSIBILITY_LIVE_REGION_POLITE);addView(status,new LayoutParams(-1,-2));
        question.setText(draft.getString("nota_draft",""));question.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int count,int after){}public void afterTextChanged(Editable e){draft.edit().putString("nota_draft",e.toString()).apply();send.setEnabled(busy||e.toString().trim().length()>0);}public void onTextChanged(CharSequence s,int st,int before,int count){}});question.setOnEditorActionListener((v,action,event)->{if(action==EditorInfo.IME_ACTION_SEND&&!busy){host.send(question.getText().toString());return true;}return false;});render();status();
    }
    private void persist(){storage.edit().putString("document",conversations.save()).apply();}
    JSONArray context(){return conversations.current().context();}
    boolean alwaysSearch(){return search;}
    boolean busy(){return busy;}
    private void status(){status.setText(busy?"Working on your reply":cloud.isChecked()?"Cloud on · Check sources for important details":"Cloud off · Local launcher commands are ready");}
    void syncCloud(){syncingCloud=true;cloud.setChecked(draft.getBoolean("cloud_ai",false));syncingCloud=false;status();}
    void draft(String text){question.setText(text);question.setSelection(question.length());question.requestFocus();}
    void begin(String text){pending=text;busy=true;render();question.setText("");send.setText("■");send.setTextSize(18);send.setEnabled(true);send.setContentDescription("Stop reply");status();bottom();}
    void progress(String text){if(busy&&answer!=null)answer.setText(text);}
    void finish(LiveAnswer reply,boolean context){if(pending==null)return;conversations.append(pending,reply,context);pending=null;busy=false;persist();render();status();bottom();}
    void stop(){if(pending!=null)finish(LiveAnswer.plain("Reply stopped. You can send another message whenever you’re ready.","Stopped"),false);}
    void newChat(){host.stop();conversations.newChat();persist();question.setText("");render();status();}
    void recent(){host.stop();android.app.AlertDialog.Builder builder=new android.app.AlertDialog.Builder(getContext()).setTitle("Recent conversations · on this device");String[] titles=new String[conversations.chats.size()];for(int i=0;i<titles.length;i++)titles[i]=conversations.chats.get(i).title();Ui.themeDialog(builder.setItems(titles,(d,which)->{host.stop();conversations.select(conversations.chats.get(which).id);persist();question.setText("");render();status();}).setNegativeButton("Close",null).create());}
    void delete(){Ui.themeDialog(new android.app.AlertDialog.Builder(getContext()).setTitle("Delete this conversation?").setMessage("This removes its messages from this device.").setNegativeButton("Cancel",null).setPositiveButton("Delete",(d,w)->{host.stop();conversations.deleteCurrent();persist();question.setText("");render();}).create());}
    private TextView label(String text,int size,int color){TextView v=Ui.text(getContext(),text,size,color);v.setShadowLayer(0,0,0,0);return v;}
    private void render(){
        transcript.removeAllViews();if(conversations.current().turns.isEmpty()&&pending==null)welcome();
        for(NotaConversation.Turn t:conversations.current().turns){user(t.question);assistant(t.answer,t.question);}
        if(pending!=null){user(pending);assistant(LiveAnswer.plain("Thinking about your question", "Nth Nota"),pending);}
        send.setText(busy?"■":"↑");send.setTextSize(busy?18:24);send.setContentDescription(busy?"Stop reply":"Send to Nth Nota AI");send.setEnabled(busy||!question.getText().toString().trim().isEmpty());
    }
    private void welcome(){
        Context c=getContext();LinearLayout welcome=Ui.column(c);welcome.setGravity(Gravity.CENTER);welcome.setPadding(Ui.dp(c,12),Ui.dp(c,14),Ui.dp(c,12),Ui.dp(c,16));TextView mark=label("Nᵗʰ",30,Ui.ACCENT);mark.setGravity(Gravity.CENTER);mark.setTypeface(Typeface.create("sans-serif-light",Typeface.NORMAL));mark.setBackground(Ui.satin(c,0xAA4C5C82,0xCC123344,20));welcome.addView(mark,new LayoutParams(Ui.dp(c,70),Ui.dp(c,70)));TextView heading=label("What’s on your mind?",27,Ui.TEXT);heading.setGravity(Gravity.CENTER);heading.setTypeface(Typeface.create("sans-serif-light",Typeface.NORMAL));LayoutParams hp=new LayoutParams(-1,-2);hp.topMargin=Ui.dp(c,18);welcome.addView(heading,hp);TextView detail=label("Ask, explore, or shape your desktop.",14,Ui.MUTED);detail.setGravity(Gravity.CENTER);detail.setPadding(0,Ui.dp(c,10),0,Ui.dp(c,24));welcome.addView(detail);
        String[][] prompts={{"Explore an idea","Why does the sky change color at sunset?"},{"Make something","Help me write a warm thank-you message."},{"Plan my day","Help me plan a relaxed, productive day."},{"Shape my desktop","How can I make my desktop feel calmer?"}};for(String[] prompt:prompts){Button b=Ui.quiet(c,prompt[0]+"  ↗",()->draft(prompt[1]));b.setTextSize(14);b.setGravity(Gravity.START|Gravity.CENTER_VERTICAL);b.setBackground(Ui.touch(c,Ui.surface(0x282C5269,14,c),14));LayoutParams bp=new LayoutParams(-1,-2);bp.bottomMargin=Ui.dp(c,7);welcome.addView(b,bp);}transcript.addView(welcome,new LayoutParams(-1,-2));
    }
    private void user(String text){TextView user=label(text,16,Ui.TEXT);user.setTextIsSelectable(true);user.setPadding(Ui.dp(getContext(),14),Ui.dp(getContext(),12),Ui.dp(getContext(),14),Ui.dp(getContext(),12));user.setBackground(Ui.surface(0xAA294152,18,getContext()));LayoutParams p=new LayoutParams(-2,-2);p.gravity=Gravity.END;p.leftMargin=Ui.dp(getContext(),28);p.topMargin=Ui.dp(getContext(),14);p.bottomMargin=Ui.dp(getContext(),18);transcript.addView(user,p);}
    private void assistant(LiveAnswer reply,String query){
        Context c=getContext();LinearLayout block=Ui.column(c);block.setPadding(Ui.dp(c,2),0,Ui.dp(c,2),Ui.dp(c,8));LinearLayout heading=Ui.row(c);TextView name=label("Nᵗʰ  ·  Nth Nota",12,Ui.ACCENT);name.setTypeface(null,Typeface.BOLD);heading.addView(name,new LayoutParams(0,-2,1));if(!busy||!reply.kind.equals("Nth Nota")){Button copy=Ui.quiet(c,"Copy",()->{android.content.ClipboardManager clipboard=(android.content.ClipboardManager)c.getSystemService(Context.CLIPBOARD_SERVICE);clipboard.setPrimaryClip(ClipData.newPlainText("Nth Nota reply",reply.text));Toast.makeText(c,"Reply copied",Toast.LENGTH_SHORT).show();});copy.setTextSize(12);heading.addView(copy,new LayoutParams(-2,Ui.dp(c,44)));}block.addView(heading);answer=label(reply.text,16,Ui.TEXT);answer.setLineSpacing(Ui.dp(c,4),1);answer.setTextIsSelectable(true);answer.setAccessibilityLiveRegion(ACCESSIBILITY_LIVE_REGION_POLITE);answer.setTag("nota-answer");block.addView(answer,new LayoutParams(-1,-2));TextView meta=label(reply.kind+(reply.checkedAt>0?" · "+java.text.DateFormat.getDateTimeInstance(java.text.DateFormat.SHORT,java.text.DateFormat.SHORT).format(new java.util.Date(reply.checkedAt)):""),11,Ui.MUTED);meta.setPadding(0,Ui.dp(c,8),0,Ui.dp(c,2));block.addView(meta);suggestions=Ui.column(c);block.addView(suggestions);int i=0;for(LiveAnswer.Source source:reply.sources){Button link=Ui.quiet(c,"↗  "+source.title+"\n"+source.detail,()->open(source.url));link.setTextSize(12);link.setGravity(Gravity.START|Gravity.CENTER_VERTICAL);link.setTag("nota-source:"+(++i));link.setContentDescription("Open source: "+source.title);suggestions.addView(link,new LayoutParams(-1,-2));}if(reply.searchFallback){Button web=Ui.quiet(c,"Search the web",()->open("https://www.google.com/search?q="+android.net.Uri.encode(query)));web.setTag("nota-web-search");suggestions.addView(web,new LayoutParams(-1,-2));}transcript.addView(block,new LayoutParams(-1,-2));
    }
    private void open(String url){if(!LiveAnswer.safeLink(url))return;try{getContext().startActivity(new Intent(Intent.ACTION_VIEW,android.net.Uri.parse(url)));}catch(ActivityNotFoundException|SecurityException missing){Toast.makeText(getContext(),"A browser is unavailable.",Toast.LENGTH_SHORT).show();}}
    private void bottom(){scroll.post(()->scroll.smoothScrollTo(0,Math.max(0,transcript.getHeight()-scroll.getHeight())));}
}
